function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function getTelegramContext(source) {
  const payload = source.payload || {};
  const message = source.message || payload.message || payload.body?.message || {};
  const chatId = source.chatId || message.chat?.id || payload.chatId || '';
  const rawText = String(source.rawText || source.text || message.text || message.caption || payload.text || '').trim();
  return { payload, message, chatId, rawText };
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^[\"'“”‘’]+|[\"'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

const source = $('Execute Workflow Trigger').item.json || {};
const ctx = getTelegramContext(source);
const raw = ctx.rawText;
const text = normalize(raw);
const prefixes = ['tao sheet', 'tao bang tinh', 'create sheet'];
let body = raw;
for (const prefix of prefixes) {
  if (text.startsWith(prefix + ' ')) {
    body = raw.slice(prefix.length + 1).trim();
    break;
  }
}

const title = cleanName(source.title || source.sheetTitle || source.fileName || body);

return [{
  json: {
    ...source,
    payload: ctx.payload,
    message: ctx.message,
    chatId: ctx.chatId,
    rawText: raw,
    text,
    title,
    hasTarget: Boolean(title),
    response: title ? '' : '📊 <b>Tao Google Sheet</b>\n\nVi du: <code>tao sheet Chi tieu</code>'
  }
}];

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;');
}

const source = $('Prepare Action').item.json || {};
const sheet = $input.item.json || {};
const spreadsheetId = sheet.spreadsheetId || '';
const title = sheet.properties?.title || source.title || 'Khong ro ten';
const link = spreadsheetId ? `https://docs.google.com/spreadsheets/d/${spreadsheetId}/edit` : '';

if (!source.chatId) {
  throw new Error('Missing chatId while formatting Google Sheets create response.');
}

let text = '✅ <b>Da tao Google Sheet</b>\n\n';
text += `<b>${escapeHtml(title)}</b>\n`;
if (spreadsheetId) text += `ID: <code>${escapeHtml(spreadsheetId)}</code>\n`;
if (link) text += `🔗 <a href="${escapeHtml(link)}">Mo bang tinh</a>`;

return [{ json: { chatId: source.chatId, text: text.trim() } }];
